import { randomUUID } from "crypto";
import type { CommunityMessage } from "./commandCenterService.js";

function getSupabaseConfig() {
  const url = (process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL || "").replace(/\/$/, "");
  // Prefer the current opaque secret key. Keep the legacy service-role key as a
  // compatibility fallback for older Vercel configurations.
  const key =
    process.env.SUPABASE_SECRET_KEY ||
    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    "";
  return { url, key };
}

export function getSupabaseCommunityStatus() {
  const { url, key } = getSupabaseConfig();
  return {
    enabled: Boolean(url && key),
    urlConfigured: Boolean(url),
    secretConfigured: Boolean(key),
  };
}

export const isSupabaseCommunityEnabled = Boolean(
  getSupabaseConfig().url && getSupabaseConfig().key
);

function headers(extra: Record<string, string> = {}) {
  const { key } = getSupabaseConfig();
  return {
    apikey: key,
    Authorization: `Bearer ${key}`,
    "Content-Type": "application/json",
    ...extra,
  };
}

let communityDownUntil = 0;
async function supabaseRequest(path: string, init: RequestInit = {}) {
  const { url, key } = getSupabaseConfig();
  if (!url || !key) {
    throw new Error(
      "Supabase community backend is not configured. Set SUPABASE_URL and SUPABASE_SECRET_KEY in the Vercel Production environment."
    );
  }

  if (Date.now() < communityDownUntil) {
    throw new Error("Supabase community backend is unreachable (fetch failed, ENOTFOUND) — retrying shortly.");
  }
  let response: Response;
  try {
    response = await fetch(`${url}/rest/v1/${path}`, {
      ...init,
      headers: headers((init.headers || {}) as Record<string, string>),
      signal: init.signal ?? AbortSignal.timeout(8000),
    });
  } catch (err) {
    communityDownUntil = Date.now() + 60_000;
    throw err;
  }
  const body = await response.text();
  let data: any = null;
  try {
    data = body ? JSON.parse(body) : null;
  } catch {
    data = body;
  }

  if (!response.ok) {
    const detail = typeof data === "string" ? data : JSON.stringify(data);
    throw new Error(`Supabase ${response.status}: ${detail}`);
  }
  return data;
}

async function ensureMediaBucket() {
  const { url, key } = getSupabaseConfig();
  if (!url || !key) return false;
  const response = await fetch(url + '/storage/v1/bucket', {
    signal: AbortSignal.timeout(15000),
    method: 'POST',
    headers: { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: 'primepipfx-media',
      name: 'primepipfx-media',
      public: true,
      file_size_limit: 524288000,
    }),
  });
  return response.ok || response.status === 409;
}

export async function uploadMediaSupabase(params: {
  id: string;
  data: string;
  mimeType: string;
}) {
  const { url, key } = getSupabaseConfig();
  if (!url || !key) throw new Error('Supabase storage is not configured.');
  await ensureMediaBucket();
  const clean = params.data.includes(',') ? params.data.split(',')[1] : params.data;
  const buffer = Buffer.from(clean, 'base64');
  const ext = params.mimeType.includes('mp4') ? 'm4a' : params.mimeType.includes('ogg') ? 'ogg' : params.mimeType.includes('png') ? 'png' : params.mimeType.includes('jpeg') ? 'jpg' : params.mimeType.includes('webm') ? 'webm' : 'bin';
  const objectPath = 'media/' + params.id + '.' + ext;
  const response = await fetch(url + '/storage/v1/object/primepipfx-media/' + objectPath, {
    signal: AbortSignal.timeout(15000),
    method: 'POST',
    headers: {
      apikey: key,
      Authorization: 'Bearer ' + key,
      'Content-Type': params.mimeType || 'application/octet-stream',
      'x-upsert': 'true',
    },
    body: buffer,
  });
  if (!response.ok) {
    const detail = await response.text();
    throw new Error('Supabase media upload failed: ' + detail);
  }
  return '/api/media/voice/' + params.id;
}

export async function readMediaObjectSupabase(id: string) {
  const { url, key } = getSupabaseConfig();
  if (!url || !key) return null;
  const prefix = 'media/' + id;
  const response = await fetch(url + '/storage/v1/object/list/primepipfx-media', {
    signal: AbortSignal.timeout(15000),
    method: 'POST',
    headers: { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
    body: JSON.stringify({ prefix, limit: 10 }),
  });
  if (!response.ok) return null;
  const rows = await response.json().catch(() => []);
  const row = Array.isArray(rows) ? rows.find((item: any) => typeof item?.name === 'string' && item.name.startsWith('media/' + id + '.')) : null;
  if (!row) return null;
  const ext = String(row.name).split('.').pop() || 'bin';
  const objectUrl = url + '/storage/v1/object/primepipfx-media/' + prefix + '.' + ext;
  const file = await fetch(objectUrl, { headers: { apikey: key, Authorization: 'Bearer ' + key }, signal: AbortSignal.timeout(15000) });
  if (!file.ok) return null;
  return { response: file, contentType: file.headers.get('content-type') || 'application/octet-stream' };
}

export async function recordSupabaseHeartbeat(userId: string) {
  const clean = String(userId || '').trim();
  if (!clean) return false;
  await supabaseRequest(`trader_profiles?user_id=eq.${encodeURIComponent(clean)}`, {
    method: "PATCH",
    headers: { Prefer: "return=minimal" },
    body: JSON.stringify({ last_seen_at: new Date().toISOString() }),
  });
  return true;
}

export async function upsertTraderProfile(user: {
  id: string;
  username: string;
  displayName: string;
  role: string;
}) {
  await supabaseRequest("trader_profiles?on_conflict=user_id", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify({
      user_id: user.id,
      username: user.username,
      display_name: user.displayName,
      role: user.role === "ADMIN" ? "ADMIN" : "CUSTOMER",
      last_seen_at: new Date().toISOString(),
    }),
  });
}

export async function syncTraderProfiles(
  users: Array<{ id: string; username: string; name?: string; role?: string }>
) {
  if (!getSupabaseCommunityStatus().enabled || !users.length) return;
  const ids = users.map((u) => u.id).filter(Boolean);
  const existingRows = await supabaseRequest(
    `trader_profiles?user_id=in.(${ids.map((id) => encodeURIComponent(id)).join(",")})&select=user_id,last_seen_at`
  );
  const existing = new Map<string, any>(
    (Array.isArray(existingRows) ? existingRows : []).map((row: any) => [String(row.user_id), row])
  );

  await supabaseRequest("trader_profiles?on_conflict=user_id", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify(
      users.map((u) => ({
        user_id: u.id,
        username: u.username,
        display_name: u.name || u.username,
        role: u.role === "ADMIN" ? "ADMIN" : "CUSTOMER",
        last_seen_at: existing.get(u.id)?.last_seen_at || null,
      }))
    ),
  });
}

export async function readCommunityMessagesSupabase(): Promise<CommunityMessage[]> {
  // Keep the primary feed query independent from optional read/listen receipts.
  // A receipt/profile problem must never make the whole Community feed fail.
  const rows = await supabaseRequest(
    "community_messages?select=id,user_id,text_content,message_type,attachment_path,attachment_name,attachment_mime_type,attachment_size,created_at,trader_profiles!community_messages_user_id_fkey(username,display_name,role)&message_type=in.(TEXT,VOICE,IMAGE,FILE)&order=created_at.asc&limit=500"
  );

  const messages: CommunityMessage[] = (Array.isArray(rows) ? rows : []).map((row: any) => ({
    id: String(row.id),
    userId: row.user_id,
    username: row.trader_profiles?.username || row.user_id,
    userRole: (row.trader_profiles?.role === "ADMIN" ? "ADMIN" : "CUSTOMER") as 'ADMIN' | 'CUSTOMER',
    displayName:
      row.trader_profiles?.display_name ||
      row.trader_profiles?.username ||
      row.user_id,
    text: row.text_content || "",
    attachmentUrl: row.attachment_path || undefined,
    attachmentName: row.attachment_name || undefined,
    attachmentSize: row.attachment_size || undefined,
    timestamp: new Date(row.created_at).getTime(),
    timePkt: new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Karachi",
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    }).format(new Date(row.created_at)),
    datePkt: new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Karachi",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(new Date(row.created_at)),
  }));

  const ids = messages.map((message: any) => message.id).filter(Boolean);
  if (!ids.length) return messages;

  // Receipts are enrichment only. If this secondary query is unavailable
  // because of a schema/RLS/cache issue, return the messages without receipts.
  try {
    const seenRows = await supabaseRequest(
      `community_message_seen?select=message_id,user_id,seen_at,listened_at&message_id=in.(${ids.join(",")})&order=seen_at.asc`
    );
    const seenUsers = Array.from(new Set((Array.isArray(seenRows) ? seenRows : []).map((row: any) => String(row.user_id))));
    const profileRows = seenUsers.length
      ? await supabaseRequest(`trader_profiles?user_id=in.(${seenUsers.map((id) => encodeURIComponent(id)).join(",")})&select=user_id,username,display_name`)
      : [];
    const profileMap = new Map<string, any>(
      (Array.isArray(profileRows) ? profileRows : []).map((row: any) => [String(row.user_id), row])
    );
    const seenByMessage = new Map<string, any[]>();
    const listenedByMessage = new Map<string, any[]>();
    for (const row of Array.isArray(seenRows) ? seenRows : []) {
      const profile = profileMap.get(String(row.user_id));
      const person = {
        userId: row.user_id,
        username: profile?.username || row.user_id,
        displayName: profile?.display_name || profile?.username || row.user_id,
        seenAt: row.seen_at ? new Date(row.seen_at).getTime() : undefined,
        listenedAt: row.listened_at ? new Date(row.listened_at).getTime() : undefined,
      };
      const seenList = seenByMessage.get(String(row.message_id)) || [];
      seenList.push(person);
      seenByMessage.set(String(row.message_id), seenList);
      if (row.listened_at) {
        const listenedList = listenedByMessage.get(String(row.message_id)) || [];
        listenedList.push(person);
        listenedByMessage.set(String(row.message_id), listenedList);
      }
    }
    for (const message of messages) {
      message.seenBy = seenByMessage.get(message.id) || [];
      (message as any).listenedBy = listenedByMessage.get(message.id) || [];
    }
  } catch (receiptError: any) {
    console.warn("[COMMUNITY READ] Receipt enrichment skipped:", receiptError?.message || receiptError);
    for (const message of messages) {
      message.seenBy = [];
      (message as any).listenedBy = [];
    }
  }

  return messages;
}

export async function postCommunityMessageSupabase(msg: {
  userId: string;
  text?: string;
  messageType?: string;
  attachmentPath?: string;
  attachmentName?: string;
  attachmentMimeType?: string;
  attachmentSize?: number;
}) {
  const rows = await supabaseRequest("community_messages", {
    method: "POST",
    headers: { Prefer: "return=representation" },
    body: JSON.stringify({
      user_id: msg.userId,
      text_content: (msg.text || "").trim().slice(0, 4000),
      message_type: msg.messageType || "TEXT",
      attachment_path: msg.attachmentPath || null,
      attachment_name: msg.attachmentName || null,
      attachment_mime_type: msg.attachmentMimeType || null,
      attachment_size: msg.attachmentSize || null,
    }),
  });

  return Array.isArray(rows) ? rows[0] : rows;
}

export async function markCommunityMessagesSeenSupabase(
  messageIds: string[],
  userId: string
) {
  if (!messageIds.length) return 0;

  const payload = messageIds.map((messageId) => ({
    message_id: messageId,
    user_id: userId,
    seen_at: new Date().toISOString(),
  }));

  await supabaseRequest(
    "community_message_seen?on_conflict=message_id,user_id",
    {
      method: "POST",
      headers: {
        Prefer: "resolution=merge-duplicates,return=minimal",
      },
      body: JSON.stringify(payload),
    }
  );

  return messageIds.length;
}

export async function markCommunityMessageListenedSupabase(messageId: string, userId: string) {
  const existingRows = await supabaseRequest(
    `community_message_seen?message_id=eq.${encodeURIComponent(messageId)}&user_id=eq.${encodeURIComponent(userId)}&select=message_id&limit=1`
  );
  const now = new Date().toISOString();
  if (Array.isArray(existingRows) && existingRows.length) {
    await supabaseRequest(
      `community_message_seen?message_id=eq.${encodeURIComponent(messageId)}&user_id=eq.${encodeURIComponent(userId)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({ listened_at: now }),
      }
    );
  } else {
    await supabaseRequest("community_message_seen", {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ message_id: messageId, user_id: userId, seen_at: now, listened_at: now }),
    });
  }
  return true;
}

export async function getSupabaseTraderById(userId: string) {
  const cleanId = String(userId || "").trim();
  if (!cleanId) return null;

  const profileRows = await supabaseRequest(
    `trader_profiles?user_id=eq.${encodeURIComponent(cleanId)}&select=user_id,username,display_name,role,last_seen_at,created_at,avatar_url&limit=1`
  );
  if (Array.isArray(profileRows) && profileRows[0]) return profileRows[0];

  // The community profile can lag behind the durable PrimePipFX identity store.
  // Recover it directly from the durable user registry instead of relying on a
  // serverless instance's local JSON files.
  const userRows = await supabaseRequest(
    `primepipfx_users?legacy_user_id=eq.${encodeURIComponent(cleanId)}&select=legacy_user_id,username,name,role,show_active_status,created_at&limit=1`
  );
  const user = Array.isArray(userRows) ? userRows[0] : null;
  if (!user) return null;

  await upsertTraderProfile({
    id: user.legacy_user_id,
    username: user.username,
    displayName: user.name || user.username,
    role: user.role || "CUSTOMER",
  });

  return {
    user_id: user.legacy_user_id,
    username: user.username,
    display_name: user.name || user.username,
    role: user.role === "ADMIN" ? "ADMIN" : "CUSTOMER",
    last_seen_at: null,
    created_at: user.created_at,
  };
}

export async function getCommunityTradersSupabase() {
  return supabaseRequest(
    "trader_profiles?select=user_id,username,display_name,role,last_seen_at,created_at&order=created_at.asc&limit=1000"
  );
}

export async function getSupabaseTraderDirectory(excludeUserId?: string) {
  const rows = await supabaseRequest(
    "primepipfx_users?select=legacy_user_id,username,name,role,created_at,show_active_status&order=created_at.asc&limit=1000"
  );
  const excluded = String(excludeUserId || "");
  return (Array.isArray(rows) ? rows : [])
    .filter((row: any) => String(row.legacy_user_id || "") !== excluded)
    .map((row: any) => ({
      user_id: row.legacy_user_id,
      username: row.username,
      display_name: row.name || row.username,
      role: row.role === "ADMIN" ? "ADMIN" : "CUSTOMER",
      last_seen_at: null,
      created_at: row.created_at,
      show_active_status: row.show_active_status !== false,
    }));
}

export async function listSupabaseFriends(userId: string) {
  const friendshipRows = await supabaseRequest(
    `friendships?or=(user_id_1.eq.${encodeURIComponent(userId)},user_id_2.eq.${encodeURIComponent(userId)})&select=user_id_1,user_id_2,created_at&order=created_at.asc`
  );
  const rows = Array.isArray(friendshipRows) ? friendshipRows : [];
  const friendIds = rows.map((row: any) => row.user_id_1 === userId ? row.user_id_2 : row.user_id_1);
  if (!friendIds.length) return [];
  let profiles = await supabaseRequest(
    `trader_profiles?user_id=in.(${friendIds.map((id: string) => encodeURIComponent(id)).join(",")})&select=user_id,username,display_name,role,last_seen_at,avatar_url`
  );
  if (!Array.isArray(profiles) || profiles.length < friendIds.length) {
    const directory = await getSupabaseTraderDirectory();
    const byId = new Map(directory.map((p: any) => [String(p.user_id), p]));
    profiles = friendIds.map((id: string) => byId.get(String(id))).filter(Boolean);
  }
  const profileMap = new Map<string, any>((Array.isArray(profiles) ? profiles : []).map((p: any) => [String(p.user_id), p]));
  return rows.map((row: any) => {
    const friendId = row.user_id_1 === userId ? row.user_id_2 : row.user_id_1;
    const profile = profileMap.get(String(friendId));
    const lastSeen = profile?.last_seen_at ? new Date(profile.last_seen_at).getTime() : 0;
    const online = lastSeen > Date.now() - 2 * 60 * 1000;
    return {
      id: `friendship:${[userId, friendId].sort().join(":")}`,
      friendId,
      friendUsername: profile?.username || friendId,
      friendDisplayName: profile?.display_name || profile?.username || friendId,
      onlineStatus: online ? "ONLINE" : "OFFLINE",
      isOnline: online,
      lastSeen,
      avatarUrl: profile?.avatar_url || undefined,
      since: row.created_at,
    };
  });
}

export async function getSupabaseFriendRequests(userId: string) {
  const rows = await supabaseRequest(
    `friend_requests?or=(sender_id.eq.${encodeURIComponent(userId)},receiver_id.eq.${encodeURIComponent(userId)})&status=eq.PENDING&select=id,sender_id,receiver_id,status,created_at,updated_at&order=created_at.desc`
  );
  const requests = Array.isArray(rows) ? rows : [];
  if (!requests.length) return { incomingRequests: [], outgoingRequests: [] };
  const ids = Array.from(new Set(requests.flatMap((r: any) => [r.sender_id, r.receiver_id])));
  let profiles = await supabaseRequest(
    `trader_profiles?user_id=in.(${ids.map((id: string) => encodeURIComponent(id)).join(",")})&select=user_id,username,display_name`
  );
  if (!Array.isArray(profiles) || profiles.length < ids.length) {
    const directory = await getSupabaseTraderDirectory();
    const byId = new Map(directory.map((p: any) => [String(p.user_id), p]));
    profiles = ids.map((id: string) => byId.get(String(id))).filter(Boolean);
  }
  const profileMap = new Map<string, any>((Array.isArray(profiles) ? profiles : []).map((p: any) => [String(p.user_id), p]));
  const mapRequest = (r: any) => ({
    id: String(r.id),
    senderId: r.sender_id,
    senderUsername: profileMap.get(String(r.sender_id))?.username || r.sender_id,
    senderDisplayName: profileMap.get(String(r.sender_id))?.display_name || profileMap.get(String(r.sender_id))?.username || r.sender_id,
    receiverId: r.receiver_id,
    receiverUsername: profileMap.get(String(r.receiver_id))?.username || r.receiver_id,
    receiverDisplayName: profileMap.get(String(r.receiver_id))?.display_name || profileMap.get(String(r.receiver_id))?.username || r.receiver_id,
    createdAt: r.created_at,
  });
  return {
    incomingRequests: requests.filter((r: any) => r.receiver_id === userId).map(mapRequest),
    outgoingRequests: requests.filter((r: any) => r.sender_id === userId).map(mapRequest),
  };
}

export async function createSupabaseFriendRequest(params: { senderId: string; receiverId: string }) {
  const existingRows = await supabaseRequest(
    `friend_requests?or=(and(sender_id.eq.${encodeURIComponent(params.senderId)},receiver_id.eq.${encodeURIComponent(params.receiverId)}),and(sender_id.eq.${encodeURIComponent(params.receiverId)},receiver_id.eq.${encodeURIComponent(params.senderId)}))&select=id,sender_id,receiver_id,status&limit=1`
  );
  const existing = Array.isArray(existingRows) ? existingRows[0] : null;
  if (existing?.status === "ACCEPTED") return { success: false, error: "Already friends" };
  if (existing?.status === "PENDING") return { success: false, error: "Request already pending" };
  if (existing?.status === "BLOCKED") return { success: false, error: "Unable to send request" };

  if (existing) {
    const rows = await supabaseRequest(
      `friend_requests?id=eq.${encodeURIComponent(existing.id)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify({ sender_id: params.senderId, receiver_id: params.receiverId, status: "PENDING", updated_at: new Date().toISOString() }),
      }
    );
    return { success: true, record: Array.isArray(rows) ? rows[0] : rows };
  }

  const rows = await supabaseRequest("friend_requests", {
    method: "POST",
    headers: { Prefer: "return=representation" },
    body: JSON.stringify({ sender_id: params.senderId, receiver_id: params.receiverId, status: "PENDING" }),
  });
  return { success: true, record: Array.isArray(rows) ? rows[0] : rows };
}

export async function respondToSupabaseFriendRequest(params: {
  requestId: string;
  actingUserId: string;
  status: "ACCEPTED" | "REJECTED" | "BLOCKED" | "REMOVED";
  friendUserId?: string;
}) {
  if (params.status === "REMOVED") {
    const friendUserId = String(params.friendUserId || "");
    if (!friendUserId) return { success: false, error: "Friend user ID is required." };
    const userIds = [params.actingUserId, friendUserId].sort();
    await supabaseRequest(
      `friendships?user_id_1=eq.${encodeURIComponent(userIds[0])}&user_id_2=eq.${encodeURIComponent(userIds[1])}`,
      { method: "DELETE", headers: { Prefer: "return=minimal" } }
    );
    return { success: true };
  }

  const rows = await supabaseRequest(
    `friend_requests?id=eq.${encodeURIComponent(params.requestId)}&select=id,sender_id,receiver_id,status&limit=1`
  );
  const request = Array.isArray(rows) ? rows[0] : null;
  if (!request) return { success: false, error: "Request not found" };
  if (request.receiver_id !== params.actingUserId) {
    return { success: false, error: "Only the recipient can accept or reject this request." };
  }
  if (request.status !== "PENDING") return { success: false, error: "Request is no longer pending." };

  await supabaseRequest(
    `friend_requests?id=eq.${encodeURIComponent(params.requestId)}`,
    {
      method: "PATCH",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ status: params.status, updated_at: new Date().toISOString() }),
    }
  );

  if (params.status === "ACCEPTED") {
    const ids = [request.sender_id, request.receiver_id].sort();
    await supabaseRequest("friendships", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ user_id_1: ids[0], user_id_2: ids[1] }),
    });
  }
  return { success: true };
}

export async function markPrivateMessagesReadSupabase(receiverId: string, senderId: string) {
  const rows = await supabaseRequest(
    `private_messages?sender_id=eq.${encodeURIComponent(senderId)}&receiver_id=eq.${encodeURIComponent(receiverId)}&select=id`
  );
  const ids = (Array.isArray(rows) ? rows : []).map((row: any) => String(row.id));
  if (!ids.length) return 0;

  const existingRows = await supabaseRequest(
    `private_message_receipts?user_id=eq.${encodeURIComponent(receiverId)}&message_id=in.(${ids.join(",")})&select=message_id`
  );
  const existingIds = new Set((Array.isArray(existingRows) ? existingRows : []).map((row: any) => String(row.message_id)));
  const now = new Date().toISOString();

  if (existingIds.size) {
    await supabaseRequest(
      `private_message_receipts?user_id=eq.${encodeURIComponent(receiverId)}&message_id=in.(${Array.from(existingIds).join(",")})`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({ read_at: now, updated_at: now }),
      }
    );
  }

  const missingIds = ids.filter((id: string) => !existingIds.has(id));
  if (missingIds.length) {
    await supabaseRequest("private_message_receipts", {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify(missingIds.map((messageId: string) => ({
        message_id: messageId,
        user_id: receiverId,
        read_at: now,
      }))),
    });
  }

  return ids.length;
}

export async function markPrivateMessageListenedSupabase(messageId: string, userId: string) {
  const existingRows = await supabaseRequest(
    `private_message_receipts?message_id=eq.${encodeURIComponent(messageId)}&user_id=eq.${encodeURIComponent(userId)}&select=message_id&limit=1`
  );
  const now = new Date().toISOString();
  if (Array.isArray(existingRows) && existingRows.length) {
    await supabaseRequest(
      `private_message_receipts?message_id=eq.${encodeURIComponent(messageId)}&user_id=eq.${encodeURIComponent(userId)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({ read_at: now, listened_at: now, updated_at: now }),
      }
    );
  } else {
    await supabaseRequest("private_message_receipts", {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ message_id: messageId, user_id: userId, read_at: now, listened_at: now }),
    });
  }
  return true;
}

function mapPrivateMessageRow(row: any) {
  const createdAt = new Date(row.created_at).getTime();
  return {
    id: String(row.id),
    senderId: row.sender_id,
    senderUsername: row.sender?.username || row.sender_id,
    senderDisplayName: row.sender?.display_name || row.sender?.username || row.sender_id,
    receiverId: row.receiver_id,
    receiverUsername: row.receiver?.username || row.receiver_id,
    text: row.text_content || '',
    type: row.message_type === 'VOICE' ? 'VOICE' : row.message_type === 'IMAGE' ? 'IMAGE' : row.message_type === 'FILE' ? 'FILE' : 'TEXT',
    photoUrl: row.message_type === 'IMAGE' ? row.attachment_path || undefined : undefined,
    audioUrl: row.message_type === 'VOICE' ? row.attachment_path || undefined : undefined,
    audioAttachmentId: row.message_type === 'VOICE' && row.attachment_path ? String(row.attachment_path).split('/').pop() : undefined,
    audioMimeType: row.message_type === 'VOICE' ? row.attachment_mime_type || undefined : undefined,
    audioSize: row.message_type === 'VOICE' ? row.attachment_size || undefined : undefined,
    attachmentUrl: row.message_type === 'FILE' ? row.attachment_path || undefined : undefined,
    attachmentName: row.attachment_name || undefined,
    attachmentSize: row.attachment_size || undefined,
    timestamp: createdAt,
    timePkt: new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Karachi', hour: '2-digit', minute: '2-digit', hour12: true }).format(new Date(createdAt)),
    datePkt: new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Karachi', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(createdAt)),
    read: false,
  };
}

export async function readPrivateMessagesSupabase(userId1: string, userId2: string) {
  const filter = `or(and(sender_id.eq.${encodeURIComponent(userId1)},receiver_id.eq.${encodeURIComponent(userId2)}),and(sender_id.eq.${encodeURIComponent(userId2)},receiver_id.eq.${encodeURIComponent(userId1)}))`;
  const rows = await supabaseRequest(
    `private_messages?select=id,sender_id,receiver_id,text_content,message_type,attachment_path,attachment_name,attachment_mime_type,attachment_size,created_at,sender:trader_profiles!private_messages_sender_id_fkey(username,display_name),receiver:trader_profiles!private_messages_receiver_id_fkey(username,display_name)&${filter}&order=created_at.asc&limit=1000`
  );
  const messages = (Array.isArray(rows) ? rows : []).map(mapPrivateMessageRow);
  const ids = messages.map((message: any) => message.id).filter(Boolean);
  if (!ids.length) return messages;
  const receiptRows = await supabaseRequest(
    `private_message_receipts?select=message_id,user_id,read_at,listened_at&message_id=in.(${ids.join(",")})`
  );
  const receiptMap = new Map<string, any>();
  for (const receipt of Array.isArray(receiptRows) ? receiptRows : []) receiptMap.set(String(receipt.message_id) + ":" + String(receipt.user_id), receipt);
  return messages.map((message: any) => {
    const viewerId = message.receiverId === userId1 ? userId1 : userId2;
    const receipt = receiptMap.get(String(message.id) + ":" + String(viewerId));
    return {
      ...message,
      read: Boolean(receipt?.read_at),
      readAt: receipt?.read_at ? new Date(receipt.read_at).getTime() : undefined,
      listenedAt: receipt?.listened_at ? new Date(receipt.listened_at).getTime() : undefined,
    };
  });
}

