app.post('/api/auth/login', async (req, res) => {
  const { username, password, rememberMe = true } = req.body || {};
  if (!username || !password) {
    return res.status(400).json({ ok: false, error: 'Username and password are required' });
  }

  // Fast path: a known account signs in straight away. Only when it is not found here (a brand-new account
  // saved by another server, or an older student account) do we wait to re-read the stores before refusing.
  let localResult = loginUser(username, password, rememberMe);
  if (!localResult?.user) {
    await Promise.allSettled([syncLegacyStudentsToServer(true), syncUsersFromDurable(0)]);
    localResult = loginUser(username, password, rememberMe);
  } else {
    void syncLegacyStudentsToServer().catch(() => undefined);
  }
  if (localResult?.user) {
    try { recordLogin(localResult.user.id, { ip: String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '').split(',')[0].trim(), device: String(req.headers['user-agent'] || '').slice(0, 160), kind: 'login' }); } catch { /* tracking is best-effort */ }
  }

  // Administrator authentication is authoritative in the server auth store.
  // A valid admin credential must not depend on a separate identity-provider
  // login or stale Supabase credentials.
  if (localResult?.user && (
    localResult.user.isDeveloper ||
    localResult.user.role === 'ADMIN' ||
    localResult.user.role === 'DEVELOPER'
  )) {
    const maxAge = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000;
    res.cookie('primepipfx_session', localResult.token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
      sameSite: 'lax',
      maxAge,
      path: '/',
    });
    return res.json({
      ok: true,
      user: sanitizeUser(localResult.user),
      token: localResult.token,
      authMode: 'administrator',
    });
  }

  if (isSupabaseAuthEnabled) {
    try {
      const durable = await authenticatePrimePipfx(username, password, localResult?.user || null);
      if (!durable) {
        // If Supabase credentials are valid but the supplied credentials are not,
        // never dereference a missing localResult and never turn a normal bad-login
        // into a server error.
        if (!localResult) {
          return res.status(401).json({ ok: false, error: 'Invalid username or password' });
        }
        const maxAge = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000;
        res.cookie('primepipfx_session', localResult.token, {
          httpOnly: true, secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
          sameSite: 'lax', maxAge, path: '/',
        });
        return res.json({ ok: true, user: sanitizeUser(localResult.user), token: localResult.token, authMode: 'legacy-compatibility' });
      }
      const maxAge = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000;
      res.cookie('primepipfx_session', durable.accessToken, {
        httpOnly: true, secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
        sameSite: 'lax', maxAge, path: '/',
      });
      res.cookie('primepipfx_refresh', durable.refreshToken, {
        httpOnly: true, secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
        sameSite: 'lax', maxAge, path: '/',
      });
      const { cacheAuthenticatedUser } = await import('./server/authService.js');
      cacheAuthenticatedUser(durable.accessToken, durable.user, Math.min(durable.expiresIn * 1000 - 30_000, 55 * 60 * 1000));
      return res.json({ ok: true, user: sanitizeUser(durable.user), token: durable.accessToken });
    } catch (error) {
      console.error('[AUTH] Supabase login failed:', error instanceof Error ? error.message : error);
      if (localResult) {
        const maxAge = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000;
        res.cookie('primepipfx_session', localResult.token, {
          httpOnly: true, secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
          sameSite: 'lax', maxAge, path: '/',
        });
        return res.json({ ok: true, user: sanitizeUser(localResult.user), token: localResult.token, authMode: 'legacy-compatibility' });
      }
      return res.status(503).json({ ok: false, error: 'Authentication service is temporarily unavailable.' });
    }
  }

  if (!localResult) {
    return res.status(401).json({ ok: false, error: 'Invalid username or password' });
  }

  const maxAge = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000;
  res.cookie('primepipfx_session', localResult.token, {
    httpOnly: true, secure: process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL),
    sameSite: 'lax', maxAge, path: '/',
  });
  return res.json({ ok: true, user: sanitizeUser(localResult.user), token: localResult.token });
});

